/** è‡ªæ£€ä»¥å¤–éƒ¨è°ƒç”¨æ–¹èº«ä»½å‘èµ·ï¼šå‡­è¯ã€èŒƒå›´ã€é™æµéƒ½èƒ½åœ¨çœŸæœºä¸Šä¸€å¹¶éªŒè¯ã€‚ */
async function probe() {
  probing.value = true
  probeResult.value = 'æ­£åœ¨è‡ªæ£€â€¦'
  try {
    const response = await probeExternal(probeSecret.value.trim())
    const payload = response.data as { success?:boolean; message?:string; data?:unknown }
    probeOk.value = payload?.success !== false
    const count = Array.isArray(payload?.data) ? payload.data.length : 0
    probeResult.value = probeOk.value
      ? `å‡­è¯æœ‰æ•ˆï¼Œå¯è§çŸ¥è¯†åº“ ${count} ä¸ª`
      : `è°ƒç”¨å¤±è´¥ï¼š${payload?.message || 'æœªçŸ¥é”™è¯¯'}`
  } catch (e) {
    probeOk.value = false
    probeResult.value = `è°ƒç”¨å¤±è´¥ï¼š${message(e)}`
  } finally {
    probing.value = false
  }
}

/** SSE è‡ªæ£€åªè¿ 5 ç§’ï¼šç¡®è®¤é€šé“ã€å‡­è¯ä¸å¿ƒè·³åå¯ç«‹å³å…³é—­ï¼Œé¿å…é•¿æ—¶é—´å ç”¨è¿æ¥ã€‚ */
function probeSse() {
  const kb = props.bases[0]?.id
  if (!kb) {
    probeResult.value = 'ç¼ºå°‘çŸ¥è¯†åº“ï¼Œæ— æ³•è‡ªæ£€ SSE'
    probeOk.value = false
    return
  }
  probing.value = true
  probeResult.value = 'æ­£åœ¨å»ºç«‹ SSE è¿æ¥â€¦'
  const url = `/api/v1/external/stream/events?knowledgeBaseId=${kb}`
    + `&apiKey=${encodeURIComponent(probeSecret.value.trim())}`
  const source = new EventSource(url)
  let received = 0
  source.onopen = () => { probeOk.value = true; probeResult.value = 'SSE è¿æ¥å·²å»ºç«‹ï¼Œæ­£åœ¨æ¥æ”¶äº‹ä»¶â€¦' }
  source.onmessage = () => { received += 1 }
  source.onerror = () => {
    probeOk.value = false
    probeResult.value = 'SSE è¿æ¥å¤±è´¥ï¼šè¯·æ£€æŸ¥å‡­è¯ä¸ SSE é€šé“å¼€å…³'
    source.close()
    probing.value = false
  }
  window.setTimeout(() => {
    source.close()
    probing.value = false
    if (probeOk.value) probeResult.value = `SSE é€šé“æ­£å¸¸ï¼Œå·²æ”¶åˆ° ${received} æ¡æ¶ˆæ¯ï¼ˆå«å¿ƒè·³æ³¨é‡Šï¼‰`
  }, 5000)
}



